`timescale 1ns/1ps
package softmax_pkg;
  // Cubic interpolation of 2**(-f), 0 <= f <= 1, at four Chebyshev nodes.
  // Signed 26-bit, 24 fractional-bit coefficients, generated by scripts/generate_vectors.py.
  localparam logic signed [25:0] C0 = 26'sd16776255;
  localparam logic signed [25:0] C1 = -26'sd11598197;
  localparam logic signed [25:0] C2 = 26'sd3872139;
  localparam logic signed [25:0] C3 = -26'sd662425;
  localparam logic [24:0] ONE_Q24 = 25'd16777216;
  localparam logic [16:0] LOG2E_Q16 = 17'd94548;

  function automatic logic signed [25:0] mul_frac(
      input logic signed [25:0] a, input logic [15:0] f);
    logic signed [42:0] product;
    begin
      product = $signed(a) * $signed({1'b0, f});
      mul_frac = $signed(product) >>> 16;
    end
  endfunction
endpackage
